@org.springframework.web.bind.annotation.GetMapping("/owners")
public java.lang.String processFindForm(@org.springframework.web.bind.annotation.RequestParam(defaultValue = "1")
int page, org.springframework.samples.petclinic.owner.Owner owner, org.springframework.validation.BindingResult result, org.springframework.ui.Model model) {
    // allow parameterless GET request for /owners to return all records
    if (owner.getLastName() == null) {
        owner.setLastName("");// empty string signifies broadest possible search

    }
    // find owners by last name
    org.springframework.data.domain.Page<org.springframework.samples.petclinic.owner.Owner> ownersResults = findPaginatedForOwnersLastName(page, owner.getLastName());
    if (ownersResults.isEmpty()) {
        // no owners found
        result.rejectValue("lastName", "notFound", "not found");
        return "owners/findOwners";
    }
    if (ownersResults.getTotalElements() == 1) {
        // 1 owner found
        owner = ownersResults.iterator().next();
        return "redirect:/owners/" + owner.getId();
    }
    // multiple owners found
    return addPaginationModel(page, model, ownersResults);
}

