private static void downloadFileFromURL(java.lang.String urlString, java.io.File destination) throws java.lang.Exception {
    if ((java.lang.System.getenv("MVNW_USERNAME") != null) && (java.lang.System.getenv("MVNW_PASSWORD") != null)) {
        java.lang.String username = java.lang.System.getenv("MVNW_USERNAME");
        char[] password = java.lang.System.getenv("MVNW_PASSWORD").toCharArray();
        java.net.Authenticator.setDefault(new java.net.Authenticator() {
            @java.lang.Override
            protected java.net.PasswordAuthentication getPasswordAuthentication() {
                return new java.net.PasswordAuthentication(username, password);
            }
        });
    }
    java.net.URL website = new java.net.URL(urlString);
    java.nio.channels.ReadableByteChannel rbc;
    rbc = java.nio.channels.Channels.newChannel(website.openStream());
    java.io.FileOutputStream fos = new java.io.FileOutputStream(destination);
    fos.getChannel().transferFrom(rbc, 0, java.lang.Long.MAX_VALUE);
    fos.close();
    rbc.close();
}

public static void main(java.lang.String[] args) {
    java.lang.System.out.println("- Downloader started");
    java.io.File baseDirectory = new java.io.File(args[0]);
    java.lang.System.out.println("- Using base directory: " + baseDirectory.getAbsolutePath());
    // If the maven-wrapper.properties exists, read it and check if it contains a custom
    // wrapperUrl parameter.
    java.io.File mavenWrapperPropertyFile = new java.io.File(baseDirectory, MavenWrapperDownloader.MAVEN_WRAPPER_PROPERTIES_PATH);
    java.lang.String url = MavenWrapperDownloader.DEFAULT_DOWNLOAD_URL;
    if (mavenWrapperPropertyFile.exists()) {
        java.io.FileInputStream mavenWrapperPropertyFileInputStream = null;
        try {
            mavenWrapperPropertyFileInputStream = new java.io.FileInputStream(mavenWrapperPropertyFile);
            java.util.Properties mavenWrapperProperties = new java.util.Properties();
            mavenWrapperProperties.load(mavenWrapperPropertyFileInputStream);
            url = mavenWrapperProperties.getProperty(MavenWrapperDownloader.PROPERTY_NAME_WRAPPER_URL, url);
        } catch (java.io.IOException e) {
            java.lang.System.out.println(("- ERROR loading '" + MavenWrapperDownloader.MAVEN_WRAPPER_PROPERTIES_PATH) + "'");
        } finally {
            try {
                if (mavenWrapperPropertyFileInputStream != null) {
                    mavenWrapperPropertyFileInputStream.close();
                }
            } catch (java.io.IOException e) {
                // Ignore ...
            }
        }
    }
    java.lang.System.out.println("- Downloading from: " + url);
    java.io.File outputFile = new java.io.File(baseDirectory.getAbsolutePath(), MavenWrapperDownloader.MAVEN_WRAPPER_JAR_PATH);
    if (!outputFile.getParentFile().exists()) {
        if (!outputFile.getParentFile().mkdirs()) {
            java.lang.System.out.println(("- ERROR creating output directory '" + outputFile.getParentFile().getAbsolutePath()) + "'");
        }
    }
    java.lang.System.out.println("- Downloading to: " + outputFile.getAbsolutePath());
    try {
        MavenWrapperDownloader.downloadFileFromURL(url, outputFile);
        java.lang.System.out.println("Done");
        java.lang.System.exit(0);
    } catch (java.lang.Throwable e) {
        java.lang.System.out.println("- Error downloading");
        e.printStackTrace();
        java.lang.System.exit(1);
    }
}

